def topological_order(nodes, edges):
    nodes_list = list(nodes)
    node_set = set(nodes_list)

    # Build adjacency list and in-degree map
    adj = {node: [] for node in node_set}
    in_degree = {node: 0 for node in node_set}

    seen_edges = set()
    for before, after in edges:
        if before not in node_set or after not in node_set:
            raise ValueError(f"Edge contains unknown node: ({before}, {after})")
        if (before, after) in seen_edges:
            continue
        seen_edges.add((before, after))
        adj[before].append(after)
        in_degree[after] += 1

    # Use a min-heap for lexicographically smallest order
    import heapq
    heap = [node for node in node_set if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(node_set):
        raise ValueError("Graph has a cycle")

    return result

