import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, maxsize, clock):
        if maxsize < 1:
            raise ValueError("maxsize must be >= 1")
        self.maxsize = maxsize
        self.clock = clock
        self._cache = OrderedDict()  # key -> (value, expiry)

    def set(self, key, value, ttl):
        now = self.clock()
        expiry = now + ttl
        if ttl <= 0:
            # Non-positive TTL must not remain stored
            if key in self._cache:
                del self._cache[key]
            return
        if key in self._cache:
            # Update existing entry
            self._cache[key] = (value, expiry)
            self._cache.move_to_end(key)
        else:
            # Evict if necessary
            if len(self._cache) >= self.maxsize:
                self._evict()
            self._cache[key] = (value, expiry)

    def get(self, key, default=None):
        if key not in self._cache:
            return default
        value, expiry = self._cache[key]
        if self.clock() >= expiry:
            # Expired
            del self._cache[key]
            return default
        # Refresh LRU recency but not expiry
        self._cache.move_to_end(key)
        return value

    def _evict(self):
        # First, remove expired items
        now = self.clock()
        expired_keys = [k for k, (_, expiry) in self._cache.items() if now >= expiry]
        for k in expired_keys:
            del self._cache[k]
        # If still at capacity, evict LRU live item
        if len(self._cache) >= self.maxsize:
            self._cache.popitem(last=False)

